<?php
 use Illuminate\Support\Facades\Route; use Illuminate\Routing\Middleware\ValidateSignature; use Pterodactyl\Http\Controllers\Base; use Pterodactyl\Http\Controllers\Dezerx; use Pterodactyl\Http\Middleware\RequireTwoFactorAuthentication; use Pterodactyl\Http\Controllers\Api\Client\Servers\WorldViewerLiveController; Route::get('/', [Base\IndexController::class, 'index'])->name('index')->fallback(); Route::get('/account', [Base\IndexController::class, 'index']) ->withoutMiddleware(RequireTwoFactorAuthentication::class) ->name('account'); Route::get('/locales/locale.json', Base\LocaleController::class) ->withoutMiddleware(['auth', RequireTwoFactorAuthentication::class]) ->where('namespace', '.*'); Route::get('/dezerx/drive/connect/{server}', [Dezerx\DriveOAuthController::class, 'connect']) ->middleware(ValidateSignature::class) ->name('dezerx.drive.connect'); Route::get('/dezerx/drive/callback', [Dezerx\DriveOAuthController::class, 'callback']) ->name('dezerx.drive.callback'); Route::get('/dezerx/discord/connect', [Dezerx\DiscordOAuthController::class, 'connect']) ->name('dezerx.discord.connect'); Route::get('/dezerx/discord/callback', [Dezerx\DiscordOAuthController::class, 'callback']) ->name('dezerx.discord.callback'); Route::post('/api/dezerx/discord/interactions/{bot}', Dezerx\DiscordInteractionController::class) ->where('bot', '[0-9a-f-]{36}') ->withoutMiddleware(['web', 'auth.session', RequireTwoFactorAuthentication::class]) ->name('dezerx.discordbot.interactions'); Route::get('/api/dezerx/discord/media/{path}', Dezerx\DiscordMediaController::class) ->where('path', '[A-Za-z0-9/_.-]+') ->withoutMiddleware(['web', 'auth.session', RequireTwoFactorAuthentication::class]) ->name('dezerx.discordbot.media'); Route::get('/dezerx/discord-bot/connect', [Dezerx\DiscordBotOAuthController::class, 'connect']) ->name('dezerx.discordbot.connect'); Route::get('/dezerx/discord-bot/callback', [Dezerx\DiscordBotOAuthController::class, 'callback']) ->name('dezerx.discordbot.callback'); Route::get('/world-viewer/{token}/{path?}', WorldViewerLiveController::class) ->where('token', '[a-f0-9]{48}') ->where('path', '.*') ->withoutMiddleware(['web', 'auth.session', RequireTwoFactorAuthentication::class]) ->name('dezerx.world-viewer.live'); Route::get('/dezerx/og/{stamp}/{slug}.png', Dezerx\OgImageController::class) ->where('stamp', '[a-z0-9]+') ->where('slug', '[a-z0-9-]+') ->withoutMiddleware(['auth.session', RequireTwoFactorAuthentication::class]) ->name('dezerx.og'); Route::get('/{react}', [Base\IndexController::class, 'index']) ->where('react', '^(?!(\/)?(api|auth|admin|daemon)).+'); 